def gen(rng):
    def fmt(a):
        return str(len(a)) + '\n' + ' '.join(map(str, a))
    tests = [fmt([5]), fmt([1, 1]), fmt([1, 2]), fmt([0, 0, 0]), fmt([-1, 1, -1, 1]), fmt([10**9, -10**9, 10**9]), fmt([4, 4, 4, 5, 5, 6])]
    for n in (2, 4, 7, 10, 15, 25, 40):
        for _ in range(3):
            hi = rng.choice([2, 3, 5, 20])
            tests.append(fmt([rng.randint(-hi, hi) for _ in range(n)]))
    N = 100000
    tests.append(fmt([7] * N))
    tests.append(fmt([rng.randint(-10**9, 10**9) for _ in range(N)]))
    tests.append(fmt([rng.randint(1, 100) for _ in range(N)]))
    tests.append(fmt([rng.randint(-3, 3) for _ in range(N)]))
    tests.append(fmt([rng.choice([-10**9, 10**9]) for _ in range(N)]))
    return tests

